import{_ as l,l as o,o as e,c as n,v as t,p as d,x as r,d as s,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"IEX 速度颠簸","description":"","frontmatter":{"title":"IEX 速度颠簸","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/speed-bump-iex.md","filePath":"quant/speed-bump-iex.md","lastUpdated":1789023840000}'),B={name:"quant/speed-bump-iex.md"};function m(h,a,u,c,_,A){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="iex-速度颠簸" tabindex="-1">IEX 速度颠簸 <a class="header-anchor" href="#iex-速度颠簸" aria-label="Permalink to &quot;IEX 速度颠簸&quot;">​</a></h1><div class="epigraph"><p>在撮合前对所有进场消息加一段固定的、足够长的延迟，使场所在收到外部价格已经移动的市价单之前，有机会根据新行情更新或退避挂单。颠簸买的是对称的慢，不是更快的线。</p><footer>—— 据 IEX 获批成为交易所时的制度设计；机制对照 Budish, Cramton and Shim, Quarterly Journal of Economics, 2015；Baldauf and Mollner, High-Frequency Trading and Market Performance, Review of Financial Studies, 2020</footer></div><p><a href="/quant/peg-d-limit-orders">peg 与 D-limit</a>是订单层保护。缺口是场所层：IEX 用约 350 微秒的速度颠簸（coil delay）处理进场订单，同时用更快通道更新其行情与崩溃信号。Baldauf 与 Mollner（2020）分析 HFT 与市场表现；颠簸是连续协议上对相对速度的手术，不是 FBA。本课写延迟不对称如何改变狙击，不讨论品牌叙事。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BCS 竞赛的支付是「先到者通吃」。若吃单消息被强制延迟 \\(\\delta\\)，而本地挂单根据外部行情的更新路径更短，则做市商可能在狙击单到达前完成撤或 D-limit 退避。\\(\\delta\\) 需大于典型的跨市场套利延迟、小于即时性不可接受的阈值。问题是：(i) 只延迟入场、不延迟出站行情时，谁相对变慢；(ii) 碎片化下狙击是否转到无颠簸场所；(iii) 颠簸是否伤害需要立刻成交的非知情单。</p><p>对称延迟（所有人进出都加 \\(\\delta\\)）只平移绝对速度，相对竞赛仍在。IEX 的要点是<strong>不对称</strong>：保护更新相对吃单的赛跑。</p><h3 id="与频繁批量拍卖的差别" tabindex="-1">与频繁批量拍卖的差别 <a class="header-anchor" href="#与频繁批量拍卖的差别" aria-label="Permalink to &quot;与频繁批量拍卖的差别&quot;">​</a></h3><p>FBA 取消批内时间优先，用统一价。颠簸保留连续限价簿与价格–时间，只改变消息的到达时钟。队头租金仍在，只是跨市场过时报价更难被外所来的市价单收割。本地用户之间的速度竞赛可以仍在，若他们的消息经过同一 \\(\\delta\\)。设计目标是跨市场狙击，不是消灭 FIFO。</p><p><span class="marginnote">其他场所后来试验过不同长度与随机延迟。随机化改变的是方差而不是均值赛跑，博弈不同。本课以固定颠簸为机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把跨市场套利者的往返时间 \\(d_{\\mathrm{arb}}\\) 与 \\(\\delta\\) 比较。若 \\(\\delta\\gt d_{\\mathrm{arb}}\\) 的有效优势，外所狙击期望利润下降，IEX 上做市被捡下降，愿意报更窄。经验：比较 IEX 与对照所在新闻窗的实现价差、HFT 吃单占比、份额变化。用户自选择：怕被捡的做市流、零售与机构被动流可能迁入，毒性结构改变，不可把份额当质量。</p><p>Baldauf–Mollner 提醒：限制某些 HFT 策略对总福利的符号取决于信息与竞争。颠簸是限制之一，不是定理上的帕累托改进。</p>',12)),(e(),d(p,null,{default:r(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Ext%5B%22%E5%A4%96%E6%89%80%E4%BB%B7%E6%A0%BC%E8%B7%B3%22%5D%20--%3E%20Upd%5B%22IEX%20%E8%A1%8C%E6%83%85%E6%9B%B4%E6%96%B0%20%2F%20%E9%80%80%E9%81%BF%22%5D%0A%20%20Ext%20--%3E%20Snipe%5B%22%E5%A4%96%E6%89%80%E6%9D%A5%E7%9A%84%E5%90%83%E5%8D%95%22%5D%0A%20%20Snipe%20--%3E%20Delay%5B%22%E8%BF%9B%E5%9C%BA%E9%A2%A0%E7%B0%B8%20%CE%B4%22%5D%0A%20%20Upd%20--%3E%7C%22%E8%8B%A5%E5%BF%AB%E4%BA%8E%E5%BB%B6%E8%BF%9F%E5%90%8E%E7%9A%84%E5%90%83%E5%8D%95%22%7C%20Prot%5B%22%E8%BF%87%E6%97%B6%E6%8A%A5%E4%BB%B7%E8%A2%AB%E6%92%A4%E6%8E%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>颠簸把 Foucault 被捡窗口的一部分从用户速度改成场所时钟。Peg / D-limit 在这段时钟里才有意义：没有 \\(\\delta\\)，信号再好也跑不过同机房的吃单。三者是一套：信号、自动指令、延迟不对称。</p><p>碎片化：Reg NMS 的订单保护可能强制把单送到当时 NBBO 所在场所，包括无颠簸所。套利者在那些所完成价格发现，IEX 上的挂单被保护但也可能更少参与发现——Brogaard 式主动腿被设计削弱。质量要分「IEX 上的被捡」与「全国发现速度」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>350 微秒针对当时的光纤套利尺度，硬件与路径变化后最优 \\(\\delta\\) 会变。只在一个小份额场所实施，全国竞赛仍在。颠簸不阻止幌骚、填塞（消息仍可发，只是同时变慢）。对必须立即成交的单，颠簸是延迟税，他们会避开——场所客户结构因此偏被动。</p><p><span class="marginnote">把颠簸叫做「反 HFT」过粗。它针对跨市场相对速度，留下的是库存做市与本地 FIFO 博弈。</span></p><p>收盘仍是连续协议解不掉的另一点：合同钉住的价格使截止同步，颠簸改变不了指数基金必须在那一分钟成交的事实。下一课改拍卖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IEX 式固定进场颠簸用不对称延迟保护挂单更新，目标是跨市场狙击而非取消连续簿。</li><li>与 FBA 不同：保留价格–时间，只改消息时钟。</li><li>碎片化下发现可能仍发生在无颠簸场所；质量指标必须分场所与全国。</li><li>出处：Budish, Cramton and Shim, <em>QJE</em>, 2015；Baldauf and Mollner, <em>RFS</em>, 2020；Harris 对场所设计的一般讨论。</li></ul>',9))])}const x=l(B,[["render",m]]);export{F as __pageData,x as default};
